            s.bind(("0.0.0.0", port))
            return True
    except OSError:
        return False


def main():
    global data_loader

    parser = argparse.ArgumentParser(description="Harmonia Experiment Dashboard")
    parser.add_argument(
        "--phoenix-endpoint",
        default="http://localhost:6006",
