        logger.info("Phoenix endpoint not configured — skipping")
        return
    _lazy_load_phoenix()
    if not _PHOENIX_AVAILABLE:
        return
    try:
        self._phoenix_client = _phoenix_module.Client(endpoint=self.phoenix_endpoint)

